input.command:
node -e '
const get = () => fetch("http://localhost:5173/health").then(r => r.text().then(t => ({ status: r.status, body: t })));
(async () => {
  for (let i = 0; i < 60; i++) {
    try {
      const r = await get();
      console.log("server is up, HTTP " + r.status);
      console.log(r.body);
      return;
    } catch { await new Promise(res => setTimeout(res, 500)); }
  }
  console.error("server never came up");
  process.exit(1);
})();'

